//! Vectors for `blocks/iop/{hp,fold_algebra,fold_rounds}.h`, generated by
//! `scripts/cpp_vectors/hp_fold_vectors.cpp`.

use std::collections::HashMap;

use fp_core::field::ext::{F, E};
use fp_core::iop::fold_algebra::{
    fold_low, fold_low_once, fold_mask_columns, fold_mask_table, fold_mask_variables, fold_mask_weights,
    inner, pair_products,
};
use fp_core::iop::fold_rounds::{
    fold_kept_factor, fold_mask_form, FoldProverRounds, FoldVerifierRounds,
};
use fp_core::iop::hp::{
    hp_entries, hp_form, hp_place, poly_at, poly_from_values_at_0_1_2, ChallengeField,
    HidingPolynomial, Weight,
};

const VECTORS: &str = include_str!("../../fixtures/hp_fold_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

trait TestField: ChallengeField {
    fn from_hex(s: &str) -> Self;
    fn hex(&self) -> String;
    fn mk(x: u64) -> Self;
    fn parse_list(s: &str) -> Vec<Self> {
        if s == "-" {
            return Vec::new();
        }
        s.split(';').map(Self::from_hex).collect()
    }
    fn list_hex(v: &[Self]) -> String {
        v.iter().map(|x| x.hex()).collect::<Vec<_>>().join(";")
    }
}

impl TestField for F {
    fn from_hex(s: &str) -> Self {
        F(u64::from_str_radix(s, 16).unwrap())
    }
    fn hex(&self) -> String {
        format!("{:016x}", self.0)
    }
    fn mk(x: u64) -> Self {
        F(x)
    }
}

impl TestField for E {
    fn from_hex(s: &str) -> Self {
        let p: Vec<&str> = s.split(',').collect();
        assert_eq!(p.len(), 3, "E {}", s);
        E([
            F(u64::from_str_radix(p[0], 16).unwrap()),
            F(u64::from_str_radix(p[1], 16).unwrap()),
            F(u64::from_str_radix(p[2], 16).unwrap()),
        ])
    }
    fn hex(&self) -> String {
        format!("{:016x},{:016x},{:016x}", self.0[0].0, self.0[1].0, self.0[2].0)
    }
    fn mk(x: u64) -> Self {
        E([F(x), F(x + 1), F(x + 2)])
    }
}

fn assert_list<K: TestField>(got: &[K], want: &str, what: &str) {
    assert_eq!(K::list_hex(got), want, "{}", what);
}

fn assert_weight<K: TestField>(w: &Weight<K>, kv: &HashMap<&str, &str>, what: &str) {
    assert_eq!(w.d, kv["d"].parse::<u32>().unwrap(), "{} d", what);
    assert_list(&w.moment, kv["moment"], &format!("{} moment", what));
    assert_list(&w.psi, kv["psi"], &format!("{} psi", what));
    assert_eq!(w.fixed, kv["fixed"].parse::<u32>().unwrap(), "{} fixed", what);
    assert_eq!(w.fixed_inv.hex(), kv["finv"], "{} finv", what);
}

fn replay_field<K: TestField>(lines: &[&str]) {
    let mut plain: Option<Weight<K>> = None;
    let mut vars: Vec<Weight<K>> = Vec::new();
    let mut hiding: Option<HidingPolynomial<K>> = None;
    for line in lines {
        let first = line.split_whitespace().next().unwrap();
        let kv = fields(line);
        match first {
            "W" => {
                let kind = line.split_whitespace().nth(1).unwrap();
                match kind {
                    "plain" => {
                        let w = Weight::<K>::plain(3);
                        assert_weight(&w, &kv, "plain");
                        plain = Some(w);
                    }
                    "eq" => assert_weight(&Weight::<K>::equality(K::mk(7), 3), &kv, "eq"),
                    "at0" => assert_weight(&Weight::<K>::at_zero(3), &kv, "at0"),
                    "lag" => {
                        let w = Weight::<K>::lagrange(&[K::mk(0), K::mk(1), K::mk(3)], K::mk(5), 4);
                        assert_weight(&w, &kv, "lag");
                    }
                    other => panic!("W {}", other),
                }
            }
            "APPLY" => {
                let p = plain.as_ref().unwrap();
                let g = K::parse_list(kv["g"]);
                assert_eq!(p.apply(&g).hex(), kv["r"]);
                assert_eq!(p.of_one().hex(), kv["of_one"]);
            }
            "COMPLETE" => {
                let claim = K::from_hex(kv["claim"]);
                let mut q = vec![K::mk(20), K::mk(21), K::mk(22)];
                Weight::<K>::plain(3).complete(&mut q, claim);
                assert_list(&q, kv["q"], "complete");
            }
            "HP" => {
                vars = vec![
                    Weight::<K>::plain(3),
                    Weight::<K>::equality(K::mk(8), 3),
                    Weight::<K>::plain(4),
                ];
                assert_eq!(hp_entries(&vars), kv["entries"].parse::<usize>().unwrap());
                let entries: Vec<K> = (0..hp_entries(&vars)).map(|i| K::mk(100 + i as u64)).collect();
                let u = HidingPolynomial::new(&vars, &entries);
                assert_eq!(u.sum().hex(), kv["sum"]);
                hiding = Some(u);
            }
            "HPROUND" => {
                let u = hiding.as_mut().unwrap();
                assert_list(&u.round(), kv["q"], "hiding round");
            }
            "HPBIND" => {
                let u = hiding.as_mut().unwrap();
                u.bind(K::from_hex(kv["g"]));
            }
            "HPVALUE" => {
                let u = hiding.as_ref().unwrap();
                assert_eq!(u.value().hex(), line.split_whitespace().nth(1).unwrap());
            }
            "HPFORM" => {
                let gamma = K::parse_list(kv["gamma"]);
                assert_eq!(kv["k"].parse::<usize>().unwrap(), vars.len());
                assert_list(&hp_form(&vars, &gamma), kv["form"], "hp_form");
            }
            "HPPLACE" => {
                let want: Vec<usize> = line.split_whitespace().nth(1).unwrap().split(',').map(|x| x.parse().unwrap()).collect();
                let mut got = Vec::new();
                for l in 0..vars.len() {
                    for t in 0..vars[l].d as usize {
                        if l + 1 != vars.len() && t == 0 {
                            continue;
                        }
                        got.push(hp_place(&vars, l, t));
                    }
                }
                assert_eq!(got, want);
            }
            "POLYAT" => {
                let g = K::parse_list(kv["g"]);
                let x = K::from_hex(kv["x"]);
                assert_eq!(poly_at(&g, x).hex(), kv["r"]);
            }
            "POLYINTERP" => {
                let values = K::parse_list(kv["values"]);
                assert_list(&poly_from_values_at_0_1_2(values), kv["coeffs"], "interp");
            }
            "FOLDLOWONCE" => {
                let mut v = K::parse_list(kv["v"]);
                let g = K::from_hex(kv["g"]);
                fold_low_once(&mut v, &g);
                assert_list(&v, kv["out"], "fold_low_once");
            }
            "FOLDLOW" => {
                let v = K::parse_list(kv["v"]);
                let g = K::parse_list(kv["g"]);
                assert_list(&fold_low(v, &g, 3), kv["out"], "fold_low");
            }
            "PAIRPRODUCTS" => {
                let a = K::parse_list(kv["a"]);
                let m = K::parse_list(kv["m"]);
                assert_list(&pair_products(&a, &m), kv["q"], "pair_products");
            }
            "INNER" => {
                let a = K::parse_list(kv["a"]);
                let b = K::parse_list(kv["b"]);
                assert_eq!(inner(&a, &b).hex(), kv["r"]);
            }
            _ => {}
        }
    }
}

#[test]
fn hp_and_fold_algebra_vectors_match_the_cpp_reference() {
    let mut f_lines: Vec<&str> = Vec::new();
    let mut e_lines: Vec<&str> = Vec::new();
    let mut which = 0;
    for line in VECTORS.lines() {
        if let Some(f) = line.strip_prefix("FIELD ") {
            which = if f == "F" { 1 } else { 2 };
            continue;
        }
        if which == 1 {
            f_lines.push(line);
        } else if which == 2 {
            e_lines.push(line);
        }
    }
    replay_field::<F>(&f_lines);
    replay_field::<E>(&e_lines);
    assert!(!f_lines.is_empty() && !e_lines.is_empty());
}

#[test]
fn fold_rounds_vectors_match_the_cpp_reference() {
    let e = |x: u64| E([F(x), F(x + 1), F(x + 2)]);
    let mut pr: Option<FoldProverRounds<E>> = None;
    let mut vr: Option<FoldVerifierRounds<E>> = None;
    let mut last_q: Vec<E> = Vec::new();
    let mut d_table: Vec<E> = Vec::new();
    let mut lines = 0usize;

    for line in VECTORS.lines() {
        let first = line.split_whitespace().next().unwrap();
        let kv = fields(line);
        match first {
            "MASKTABLE" => {
                let k: u32 = kv["k"].parse().unwrap();
                let h: u32 = kv["h"].parse().unwrap();
                let len: usize = kv["len"].parse().unwrap();
                assert_eq!(len, fold_mask_columns(k, h));
                let w: Vec<E> = (0..2 * k as u64 + 1).map(|i| e(200 + i)).collect();
                let got = fold_mask_table(k, h, len, &w);
                assert_eq!(E::list_hex(&got), kv["table"], "fold_mask_table k={} h={}", k, h);
                lines += 1;
            }
            "MASKWEIGHTS" => {
                let k: u32 = kv["k"].parse().unwrap();
                let h: u32 = kv["h"].parse().unwrap();
                let len: usize = kv["len"].parse().unwrap();
                let g: Vec<E> = (0..k as u64).map(|i| e(10 + i)).collect();
                let got = fold_mask_weights(k, h, len, &g);
                assert_eq!(E::list_hex(&got), kv["u"], "fold_mask_weights k={} h={}", k, h);
                assert_eq!(fold_mask_variables::<E>(k).len(), k as usize);
                lines += 1;
            }
            "FOLDPROVER" => {
                let k: u32 = kv["k"].parse().unwrap();
                let h: u32 = kv["h"].parse().unwrap();
                let len: usize = kv["len"].parse().unwrap();
                let w: Vec<E> = (0..2 * k as u64 + 1).map(|i| e(200 + i)).collect();
                let n = (1usize << h) * len;
                let d: Vec<E> = (0..n as u64).map(|i| e(300 + i)).collect();
                let mu: Vec<E> = (0..n as u64).map(|i| e(400 + i)).collect();
                d_table = d.clone();
                let mut p = FoldProverRounds::new(k, h, len, &w, d, mu, e(500));
                assert_eq!(p.mask_sum().hex(), kv["mask_sum"]);
                p.start(e(501));
                let v = FoldVerifierRounds::new(p.mask_sum(), e(501), e(502));
                pr = Some(p);
                vr = Some(v);
                lines += 1;
            }
            "FOLDQ" => {
                let main = E::parse_list(kv["main"]);
                let q = pr.as_mut().unwrap().round(&main);
                assert_eq!(E::list_hex(&q), kv["q"], "fold round {}", kv["i"]);
                last_q = q;
                lines += 1;
            }
            "FOLDBIND" => {
                let g = E::from_hex(kv["g"]);
                pr.as_mut().unwrap().bind(g);
                vr.as_mut().unwrap().round(last_q[0], last_q[2], g);
                lines += 1;
            }
            "FOLDVCLAIM" => {
                assert_eq!(vr.as_ref().unwrap().claim().hex(), kv["claim"]);
                lines += 1;
            }
            "FOLDEND" => {
                let end = pr.as_ref().unwrap().end(true);
                assert_eq!(E::list_hex(&end.d), kv["d"], "fold end d");
                assert_eq!(E::list_hex(&end.mu), kv["mu"], "fold end mu");
                assert_eq!(E::list_hex(&end.fresh), kv["fresh"], "fold end fresh");
                lines += 1;
            }
            "FOLDMASKFORM" => {
                let k: u32 = kv["k"].parse().unwrap();
                let h: u32 = kv["h"].parse().unwrap();
                let eps = E::from_hex(kv["eps"]);
                let g = E::parse_list(kv["g"]);
                let out = fold_mask_form(k, h, d_table.clone(), eps, &g);
                assert_eq!(E::list_hex(&out), kv["out"], "fold_mask_form");
                lines += 1;
            }
            "KEPTFACTOR" => {
                let eps = E::from_hex(kv["eps"]);
                let g = E::parse_list(kv["g"]);
                assert_eq!(fold_kept_factor(eps, &g).hex(), kv["s"]);
                lines += 1;
            }
            _ => {}
        }
    }
    assert!(lines > 0);
}
